// Modules generated by build.mjs from the files of pdfjs-dist.

declare module 'pdfjs-assets:worker' {
  /** Source of pdf.js's worker module (pdf.worker.min.mjs). */
  const source: string;
  export default source;
}

declare module 'pdfjs-assets:files' {
  /** Base64 contents of the CMaps, standard fonts and wasm decoders, by pdf.js option name and file name. */
  const files: Readonly<Record<string, Readonly<Record<string, string>>>>;
  export default files;
}
